#!/usr/bin/env bash
# PreToolUse hook: prevents hand edits to files generated by npm and WXT.
file=$(jq -r '.tool_input.file_path // .tool_input.notebook_path // empty')
[ -z "$file" ] && exit 0

rel=${file#"${CLAUDE_PROJECT_DIR:-$PWD}"/}

case "$rel" in
  package-lock.json) reason='package-lock.json is generated by npm: change package.json and run npm install.' ;;
  .output/*) reason='.output/ is the output of wxt build: change the sources and rebuild.' ;;
  .wxt/*) reason='.wxt/ is generated by wxt prepare (postinstall): do not edit it by hand.' ;;
  *) exit 0 ;;
esac

jq -n --arg r "$reason" '{hookSpecificOutput: {hookEventName: "PreToolUse", permissionDecision: "deny", permissionDecisionReason: $r}}'
